/* @lc app=leetcode id=2045 lang=kotlin */ class Solution { fun secondMinimum(n: Int, edges: Array<IntArray>, time: Int, change: Int): Int = List(n + 1) { mutableListOf<Int>() }.also { adj -> edges.forEach { adj[it[0]].add(it[1]).run { adj[it[1]].add(it[0]) } } }.let { adj -> Array(n + 1) { IntArray(2) { 1000000000 } }.also { dist -> dist[1].set(0, 0).run { DeepRecursiveFunction<List<Pair<Int, Int>>, Unit> { q -> q.flatMap { (u, d) -> adj[u].mapNotNull { v -> if (d + 1 < dist[v][0]) dist[v].set(1, dist[v][0]).let { dist[v].set(0, d + 1) }.let { v to d + 1 } else if (d + 1 > dist[v][0] && d + 1 < dist[v][1]) dist[v].set(1, d + 1).let { v to d + 1 } else null } }.takeIf { it.isNotEmpty() }?.let { callRecursive(it) } }.invoke(listOf(1 to 0)) } }.let { dist -> (0 until dist[n][1]).fold(0) { curr, _ -> (if ((curr / change) % 2 == 1) curr + (change - curr % change) else curr) + time } } } }